sys_variable_value.value:
(function execute(inputs, outputs) {
  inputs = new DockerUtils().trimStringInputs(inputs);

  if (inputs.status_code == 200) {
    outputs.status = "Success";
    outputs.services_list = inputs.response;
    outputs.service = JSON.parse(inputs.response);
  } else {
    outputs.status = "Error";
    outputs = new DockerErrorHandler().listServicesErrorHandler(inputs,outputs);       
  }
})(inputs, outputs);

